CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id BIGINT PRIMARY KEY,name TEXT NOT NULL,menu_id BIGINT,screen TEXT NOT NULL DEFAULT 'home',wizard TEXT,started INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS groups(id TEXT PRIMARY KEY,chat_id BIGINT UNIQUE,name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'pending',cfg TEXT NOT NULL DEFAULT '{}',healthy INTEGER NOT NULL DEFAULT 0,member_count INTEGER NOT NULL DEFAULT 0,checked BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS membership(gid TEXT NOT NULL,uid BIGINT NOT NULL,present INTEGER NOT NULL DEFAULT 0,joined BIGINT NOT NULL DEFAULT 0,last_media BIGINT NOT NULL DEFAULT 0,warned INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(gid,uid));
CREATE TABLE IF NOT EXISTS access(gid TEXT NOT NULL,uid BIGINT NOT NULL,source TEXT NOT NULL,expires BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(gid,uid));
CREATE TABLE IF NOT EXISTS challenges(gid TEXT NOT NULL,uid BIGINT NOT NULL,started BIGINT NOT NULL,PRIMARY KEY(gid,uid));
CREATE TABLE IF NOT EXISTS referrals(invitee BIGINT PRIMARY KEY,inviter BIGINT NOT NULL,joined BIGINT NOT NULL,valid INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS referral_inviter_idx ON referrals(inviter,valid,joined);
CREATE TABLE IF NOT EXISTS links(url TEXT PRIMARY KEY,kind TEXT NOT NULL,gid TEXT NOT NULL,uid BIGINT NOT NULL,expires BIGINT NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS links_owner_idx ON links(uid,gid,kind);
CREATE TABLE IF NOT EXISTS bans(uid BIGINT PRIMARY KEY,permanent INTEGER NOT NULL DEFAULT 0,reason TEXT NOT NULL,created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS strikes(uid BIGINT PRIMARY KEY,count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS visits(uid BIGINT PRIMARY KEY,started BIGINT NOT NULL,expires BIGINT NOT NULL,gid TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cart(uid BIGINT NOT NULL,gid TEXT NOT NULL,PRIMARY KEY(uid,gid));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,uid BIGINT NOT NULL,items TEXT NOT NULL,total INTEGER NOT NULL,status TEXT NOT NULL,created BIGINT NOT NULL,reminded INTEGER NOT NULL DEFAULT 0,invoice TEXT,charge TEXT UNIQUE,approved_until BIGINT NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS one_pending_order ON orders(uid) WHERE status IN ('pending','checkout');
CREATE TABLE IF NOT EXISTS sessions(day TEXT PRIMARY KEY,gid TEXT NOT NULL,starts BIGINT NOT NULL,ends BIGINT NOT NULL,state TEXT NOT NULL DEFAULT 'waiting');
CREATE TABLE IF NOT EXISTS posts(gid TEXT NOT NULL,slot TEXT NOT NULL,mid BIGINT NOT NULL,body TEXT NOT NULL DEFAULT '',updated BIGINT NOT NULL,PRIMARY KEY(gid,slot));
CREATE TABLE IF NOT EXISTS messages(gid TEXT NOT NULL,mid BIGINT NOT NULL,uid BIGINT NOT NULL,album TEXT,created BIGINT NOT NULL,PRIMARY KEY(gid,mid));
CREATE INDEX IF NOT EXISTS messages_album_idx ON messages(gid,album);
CREATE TABLE IF NOT EXISTS media(gid TEXT NOT NULL,mid BIGINT NOT NULL,uid BIGINT NOT NULL,file_id TEXT NOT NULL,unique_id TEXT NOT NULL,kind TEXT NOT NULL,sha TEXT,phashes TEXT,PRIMARY KEY(gid,mid));
CREATE INDEX IF NOT EXISTS media_unique_idx ON media(unique_id);
CREATE INDEX IF NOT EXISTS media_sha_idx ON media(sha);
CREATE TABLE IF NOT EXISTS fingerprints(id TEXT PRIMARY KEY,unique_id TEXT NOT NULL,sha TEXT,phashes TEXT NOT NULL,blocked INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS fp_unique_idx ON fingerprints(unique_id);
CREATE INDEX IF NOT EXISTS fp_sha_idx ON fingerprints(sha);
CREATE TABLE IF NOT EXISTS hash_bands(band INTEGER NOT NULL,value TEXT NOT NULL,fid TEXT NOT NULL,PRIMARY KEY(band,value,fid));
CREATE INDEX IF NOT EXISTS bands_lookup_idx ON hash_bands(band,value);
CREATE TABLE IF NOT EXISTS reports(gid TEXT NOT NULL,target TEXT NOT NULL,reporter BIGINT NOT NULL,author BIGINT NOT NULL,created BIGINT NOT NULL,PRIMARY KEY(gid,target,reporter));
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,kind TEXT NOT NULL,payload TEXT NOT NULL,due BIGINT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS jobs_due_idx ON jobs(due);
CREATE TABLE IF NOT EXISTS alerts(key TEXT PRIMARY KEY,body TEXT NOT NULL,created BIGINT NOT NULL,resolved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,actor BIGINT NOT NULL,action TEXT NOT NULL,detail TEXT NOT NULL,created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS inbox(id BIGINT PRIMARY KEY,body TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,due BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS media_queue(id TEXT PRIMARY KEY,gid TEXT NOT NULL,body TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,due BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sanctions(gid TEXT NOT NULL,mid BIGINT NOT NULL,kind TEXT NOT NULL,PRIMARY KEY(gid,mid,kind));
CREATE TABLE IF NOT EXISTS access_orders(gid TEXT NOT NULL,uid BIGINT NOT NULL,order_id TEXT NOT NULL,PRIMARY KEY(gid,uid));
